"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { motion } from "framer-motion";
import {
	ArrowLeft,
	Eye,
	Hammer,
	Loader2,
	MoreHorizontal,
	Send,
	Settings,
} from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { orpc } from "@/utils/orpc";

import { useSurveyBuilder } from "./index";

const statusColors: Record<string, string> = {
	draft: "bg-neutral-100 text-neutral-600",
	published: "bg-green-100 text-green-700",
	closed: "bg-orange-100 text-orange-700",
	archived: "bg-neutral-100 text-neutral-500",
};

interface BuilderHeaderProps {
	leftActions?: React.ReactNode;
	rightActions?: React.ReactNode;
}

export function BuilderHeader({
	leftActions,
	rightActions,
}: BuilderHeaderProps) {
	const { survey, activeTab, setActiveTab } = useSurveyBuilder();
	const queryClient = useQueryClient();

	const publishMutation = useMutation(
		orpc.survey.changeStatus.mutationOptions({
			onSuccess: () => {
				toast.success("Survey published!");
				queryClient.invalidateQueries({ queryKey: ["survey"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to publish survey");
			},
		}),
	);

	const handlePublish = () => {
		if (survey.status === "draft") {
			publishMutation.mutate({ id: survey.id, status: "published" });
		}
	};

	return (
		<header className="z-20 flex shrink-0 items-center justify-between border-neutral-100 border-b bg-white px-6 py-3">
			<div className="flex items-center gap-4">
				{leftActions}
				<Button variant="ghost" size="sm" asChild>
					<Link href="/surveys">
						<ArrowLeft className="mr-2 h-4 w-4" />
						Back
					</Link>
				</Button>
				<div className="flex items-center gap-2 font-sans font-semibold text-neutral-900 text-sm">
					<span className="text-neutral-400">Surveys /</span>
					<span>{survey.title}</span>
					<Badge variant="secondary" className={statusColors[survey.status]}>
						{survey.status}
					</Badge>
				</div>
			</div>

			{/* Tab Navigation with animated indicator */}
			<div className="flex gap-1 rounded-lg bg-neutral-100 p-1">
				<button
					type="button"
					onClick={() => setActiveTab("build")}
					className={`relative flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
						activeTab === "build"
							? "text-neutral-900"
							: "text-neutral-500 hover:text-neutral-900"
					}`}
				>
					{activeTab === "build" && (
						<motion.div
							layoutId="activeTab"
							className="absolute inset-0 rounded-md bg-white shadow-sm"
							transition={{ type: "spring", stiffness: 500, damping: 30 }}
						/>
					)}
					<span className="relative z-10 flex items-center gap-2">
						<Hammer className="h-3.5 w-3.5" />
						Build
					</span>
				</button>
				<button
					type="button"
					onClick={() => setActiveTab("preview")}
					className={`relative flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
						activeTab === "preview"
							? "text-neutral-900"
							: "text-neutral-500 hover:text-neutral-900"
					}`}
				>
					{activeTab === "preview" && (
						<motion.div
							layoutId="activeTab"
							className="absolute inset-0 rounded-md bg-white shadow-sm"
							transition={{ type: "spring", stiffness: 500, damping: 30 }}
						/>
					)}
					<span className="relative z-10 flex items-center gap-2">
						<Eye className="h-3.5 w-3.5" />
						Preview
					</span>
				</button>
			</div>

			<div className="flex items-center gap-3">
				{rightActions}
				<DropdownMenu>
					<DropdownMenuTrigger render={<Button variant="ghost" size="icon" />}>
						<MoreHorizontal className="h-4 w-4" />
					</DropdownMenuTrigger>
					<DropdownMenuContent align="end">
						<DropdownMenuItem>
							<Settings className="mr-2 h-4 w-4" />
							Survey Settings
						</DropdownMenuItem>
						<DropdownMenuSeparator />
						<DropdownMenuItem className="text-red-600">
							Delete Survey
						</DropdownMenuItem>
					</DropdownMenuContent>
				</DropdownMenu>

				{survey.status === "draft" ? (
					<Button onClick={handlePublish} disabled={publishMutation.isPending}>
						{publishMutation.isPending ? (
							<Loader2 className="mr-2 h-4 w-4 animate-spin" />
						) : (
							<Send className="mr-2 h-4 w-4" />
						)}
						Publish
					</Button>
				) : (
					<Button variant="outline" asChild>
						<a
							href={`/s/${survey.slug}`}
							target="_blank"
							rel="noopener noreferrer"
						>
							<Eye className="mr-2 h-4 w-4" />
							View Survey
						</a>
					</Button>
				)}
			</div>
		</header>
	);
}

"use client";

import { ArrowLeft, ArrowRight, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useSurveyRunner } from "./context";

export function RunnerNavigation() {
	const {
		canGoBack,
		canGoNext,
		isSubmitting,
		goBack,
		goNext,
		submit,
		currentError,
	} = useSurveyRunner();

	return (
		<div className="border-neutral-200 border-t bg-white px-6 py-4">
			<div className="mx-auto max-w-2xl space-y-3">
				{currentError && (
					<div className="rounded-lg bg-red-50 px-4 py-2 text-center text-red-600 text-sm">
						{currentError}
					</div>
				)}
				<div className="flex items-center justify-between gap-4">
					<Button
						variant="ghost"
						onClick={goBack}
						disabled={!canGoBack}
						className="text-neutral-600"
					>
						<ArrowLeft className="mr-2 h-4 w-4" />
						Back
					</Button>

					{canGoNext ? (
						<Button
							onClick={goNext}
							className="bg-neutral-900 hover:bg-neutral-800"
						>
							Next
							<ArrowRight className="ml-2 h-4 w-4" />
						</Button>
					) : (
						<Button
							onClick={submit}
							disabled={isSubmitting}
							className="bg-neutral-900 hover:bg-neutral-800"
						>
							{isSubmitting ? (
								<>
									<Loader2 className="mr-2 h-4 w-4 animate-spin" />
									Submitting...
								</>
							) : (
								"Submit"
							)}
						</Button>
					)}
				</div>
			</div>
		</div>
	);
}

