import { relations } from "drizzle-orm";
import {
	boolean,
	index,
	integer,
	json,
	pgEnum,
	pgTable,
	text,
	timestamp,
	uniqueIndex,
} from "drizzle-orm/pg-core";
import { user } from "./auth";
import { organization } from "./organization";

// Survey status enum
export const surveyStatusEnum = pgEnum("survey_status", [
	"draft",
	"published",
	"closed",
	"archived",
]);

// Question type enum
export const questionTypeEnum = pgEnum("question_type", [
	"text",
	"textarea",
	"multiple_choice",
	"checkbox",
	"dropdown",
	"rating",
	"nps",
	"linear_scale",
	"date",
	"email",
	"phone",
	"file_upload",
]);

// Logic operator enum
export const logicOperatorEnum = pgEnum("logic_operator", [
	"equals",
	"not_equals",
	"contains",
	"greater_than",
	"less_than",
	"is_empty",
	"is_not_empty",
]);

// Logic action enum
export const logicActionEnum = pgEnum("logic_action", [
	"jump_to",
	"skip",
	"show",
	"hide",
	"end_survey",
]);

// Survey table
export const survey = pgTable(
	"survey",
	{
		id: text("id").primaryKey(),
		slug: text("slug").notNull(),
		title: text("title").notNull(),
		description: text("description"),
		status: surveyStatusEnum("status").default("draft").notNull(),
		settings: json("settings").$type<SurveySettings>(),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		organizationId: text("organization_id")
			.notNull()
			.references(() => organization.id, { onDelete: "cascade" }),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		uniqueIndex("survey_slug_idx").on(table.slug),
		index("survey_organizationId_idx").on(table.organizationId),
		index("survey_userId_idx").on(table.userId),
		index("survey_status_idx").on(table.status),
	],
);

// Question table
export const question = pgTable(
	"question",
	{
		id: text("id").primaryKey(),
		surveyId: text("survey_id")
			.notNull()
			.references(() => survey.id, { onDelete: "cascade" }),
		type: questionTypeEnum("type").notNull(),
		title: text("title").notNull(),
		description: text("description"),
		config: json("config").$type<QuestionConfig>(),
		required: boolean("required").default(false).notNull(),
		order: integer("order").default(0).notNull(),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("question_surveyId_idx").on(table.surveyId),
		index("question_order_idx").on(table.order),
	],
);

// Logic rule table
export const logicRule = pgTable(
	"logic_rule",
	{
		id: text("id").primaryKey(),
		surveyId: text("survey_id")
			.notNull()
			.references(() => survey.id, { onDelete: "cascade" }),
		sourceQuestionId: text("source_question_id")
			.notNull()
			.references(() => question.id, { onDelete: "cascade" }),
		operator: logicOperatorEnum("operator").notNull(),
		conditionValue: json("condition_value").$type<unknown>(),
		action: logicActionEnum("action").notNull(),
		targetQuestionId: text("target_question_id").references(() => question.id, {
			onDelete: "set null",
		}),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("logicRule_surveyId_idx").on(table.surveyId),
		index("logicRule_sourceQuestionId_idx").on(table.sourceQuestionId),
	],
);

// Response table
export const response = pgTable(
	"response",
	{
		id: text("id").primaryKey(),
		surveyId: text("survey_id")
			.notNull()
			.references(() => survey.id, { onDelete: "cascade" }),
		respondentId: text("respondent_id"),
		fingerprint: text("fingerprint"),
		metadata: json("metadata").$type<ResponseMetadata>(),
		isComplete: boolean("is_complete").default(false).notNull(),
		startedAt: timestamp("started_at").defaultNow().notNull(),
		completedAt: timestamp("completed_at"),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("response_surveyId_idx").on(table.surveyId),
		index("response_fingerprint_idx").on(table.fingerprint),
		index("response_isComplete_idx").on(table.isComplete),
	],
);

// Answer table
export const answer = pgTable(
	"answer",
	{
		id: text("id").primaryKey(),
		responseId: text("response_id")
			.notNull()
			.references(() => response.id, { onDelete: "cascade" }),
		questionId: text("question_id")
			.notNull()
			.references(() => question.id, { onDelete: "cascade" }),
		value: json("value").$type<unknown>(),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		index("answer_responseId_idx").on(table.responseId),
		index("answer_questionId_idx").on(table.questionId),
	],
);

// Relations
export const surveyRelations = relations(survey, ({ one, many }) => ({
	organization: one(organization, {
		fields: [survey.organizationId],
		references: [organization.id],
	}),
	owner: one(user, {
		fields: [survey.userId],
		references: [user.id],
	}),
	questions: many(question),
	responses: many(response),
	logicRules: many(logicRule),
}));

export const questionRelations = relations(question, ({ one, many }) => ({
	survey: one(survey, {
		fields: [question.surveyId],
		references: [survey.id],
	}),
	answers: many(answer),
	sourceLogicRules: many(logicRule, {
		relationName: "sourceQuestion",
	}),
	targetLogicRules: many(logicRule, {
		relationName: "targetQuestion",
	}),
}));

export const logicRuleRelations = relations(logicRule, ({ one }) => ({
	survey: one(survey, {
		fields: [logicRule.surveyId],
		references: [survey.id],
	}),
	sourceQuestion: one(question, {
		fields: [logicRule.sourceQuestionId],
		references: [question.id],
		relationName: "sourceQuestion",
	}),
	targetQuestion: one(question, {
		fields: [logicRule.targetQuestionId],
		references: [question.id],
		relationName: "targetQuestion",
	}),
}));

export const responseRelations = relations(response, ({ one, many }) => ({
	survey: one(survey, {
		fields: [response.surveyId],
		references: [survey.id],
	}),
	answers: many(answer),
}));

export const answerRelations = relations(answer, ({ one }) => ({
	response: one(response, {
		fields: [answer.responseId],
		references: [response.id],
	}),
	question: one(question, {
		fields: [answer.questionId],
		references: [question.id],
	}),
}));

// Type definitions for JSON fields
export interface SurveySettings {
	showProgressBar?: boolean;
	showQuestionNumbers?: boolean;
	shuffleQuestions?: boolean;
	allowMultipleResponses?: boolean;
	requireAuth?: boolean;
	collectMetadata?: boolean;
	thankYouMessage?: string;
	redirectUrl?: string;
	theme?: {
		primaryColor?: string;
		backgroundColor?: string;
		fontFamily?: string;
	};
}

export interface QuestionConfig {
	placeholder?: string;
	minLength?: number;
	maxLength?: number;
	options?: Array<{ label: string; value: string }>;
	min?: number;
	max?: number;
	step?: number;
	allowOther?: boolean;
	allowMultiple?: boolean;
	maxFiles?: number;
	maxFileSize?: number;
	acceptedFileTypes?: string[];
}

export interface ResponseMetadata {
	userAgent?: string;
	ipAddress?: string;
	referrer?: string;
	browser?: string;
	os?: string;
	device?: string;
	country?: string;
	language?: string;
	timezone?: string;
}

import { db } from "@orksys-survey/db";
import { survey } from "@orksys-survey/db/schema/survey";
import { and, count, desc, eq, ilike, inArray, or } from "drizzle-orm";
import { z } from "zod";

import {
	adminProcedure,
	organizationProcedure,
	ownerProcedure,
	publicProcedure,
} from "../index";

// Input schemas
const surveyCreateSchema = z.object({
	slug: z
		.string()
		.min(1)
		.max(100)
		.regex(/^[a-z0-9-]+$/),
	title: z.string().min(1).max(255),
	description: z.string().max(2000).optional(),
	settings: z
		.object({
			showProgressBar: z.boolean().optional(),
			showQuestionNumbers: z.boolean().optional(),
			shuffleQuestions: z.boolean().optional(),
			allowMultipleResponses: z.boolean().optional(),
			requireAuth: z.boolean().optional(),
			collectMetadata: z.boolean().optional(),
			thankYouMessage: z.string().optional(),
			redirectUrl: z.string().url().optional(),
			theme: z
				.object({
					primaryColor: z.string().optional(),
					backgroundColor: z.string().optional(),
					fontFamily: z.string().optional(),
				})
				.optional(),
		})
		.optional(),
});

const surveyUpdateSchema = surveyCreateSchema.partial();

const surveyListSchema = z.object({
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(100).default(20),
	status: z.enum(["draft", "published", "closed", "archived"]).optional(),
	search: z.string().optional(),
});

const surveyChangeStatusSchema = z.object({
	id: z.string(),
	status: z.enum(["draft", "published", "closed", "archived"]),
});

// Generate unique ID
function generateId(): string {
	return `survey_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
}

export const surveyRouter = {
	// List surveys for the organization
	list: organizationProcedure
		.input(surveyListSchema)
		.handler(async ({ input, context }) => {
			const { page, limit, status, search } = input;
			const offset = (page - 1) * limit;

			const conditions = [
				eq(survey.organizationId, context.activeOrganization.id),
			];

			if (status) {
				conditions.push(eq(survey.status, status));
			}

			if (search) {
				const searchCondition = or(
					ilike(survey.title, `%${search}%`),
					ilike(survey.description, `%${search}%`),
				);
				if (searchCondition) {
					conditions.push(searchCondition);
				}
			}

			const [surveys, totalResult] = await Promise.all([
				db
					.select()
					.from(survey)
					.where(and(...conditions))
					.orderBy(desc(survey.createdAt))
					.limit(limit)
					.offset(offset),
				db
					.select({ count: count() })
					.from(survey)
					.where(and(...conditions)),
			]);

			return {
				data: surveys,
				pagination: {
					page,
					limit,
					total: totalResult[0]?.count ?? 0,
					totalPages: Math.ceil((totalResult[0]?.count ?? 0) / limit),
				},
			};
		}),

	// Get survey by ID (organization members)
	getById: organizationProcedure
		.input(z.object({ id: z.string() }))
		.handler(async ({ input, context }) => {
			const result = await db
				.select()
				.from(survey)
				.where(
					and(
						eq(survey.id, input.id),
						eq(survey.organizationId, context.activeOrganization.id),
					),
				)
				.limit(1);

			if (!result[0]) {
				throw new Error("Survey not found");
			}

			return result[0];
		}),

	// Get published survey by slug (public - for survey runner)
	getBySlug: publicProcedure
		.input(z.object({ slug: z.string() }))
		.handler(async ({ input }) => {
			const result = await db
				.select()
				.from(survey)
				.where(and(eq(survey.slug, input.slug), eq(survey.status, "published")))
				.limit(1);

			if (!result[0]) {
				throw new Error("Survey not found");
			}

			return result[0];
		}),

	// Create new survey
	create: adminProcedure
		.input(surveyCreateSchema)
		.handler(async ({ input, context }) => {
			// Check for duplicate slug
			const existing = await db
				.select()
				.from(survey)
				.where(eq(survey.slug, input.slug))
				.limit(1);

			if (existing[0]) {
				throw new Error("A survey with this slug already exists");
			}

			const id = generateId();
			await db.insert(survey).values({
				id,
				slug: input.slug,
				title: input.title,
				description: input.description ?? null,
				status: "draft",
				settings: input.settings ?? null,
				userId: context.session.user.id,
				organizationId: context.activeOrganization.id,
			});

			const result = await db
				.select()
				.from(survey)
				.where(eq(survey.id, id))
				.limit(1);
			return result[0];
		}),

	// Update survey
	update: adminProcedure
		.input(z.object({ id: z.string(), data: surveyUpdateSchema }))
		.handler(async ({ input, context }) => {
			// Verify ownership
			const existing = await db
				.select()
				.from(survey)
				.where(
					and(
						eq(survey.id, input.id),
						eq(survey.organizationId, context.activeOrganization.id),
					),
				)
				.limit(1);

			if (!existing[0]) {
				throw new Error("Survey not found");
			}

			// Check for duplicate slug if changing
			if (input.data.slug && input.data.slug !== existing[0].slug) {
				const duplicateSlug = await db
					.select()
					.from(survey)
					.where(eq(survey.slug, input.data.slug))
					.limit(1);

				if (duplicateSlug[0]) {
					throw new Error("A survey with this slug already exists");
				}
			}

			await db
				.update(survey)
				.set({
					...(input.data.slug && { slug: input.data.slug }),
					...(input.data.title !== undefined && { title: input.data.title }),
					...(input.data.description !== undefined && {
						description: input.data.description ?? null,
					}),
					...(input.data.settings !== undefined && {
						settings: input.data.settings ?? null,
					}),
				})
				.where(eq(survey.id, input.id));

			const result = await db
				.select()
				.from(survey)
				.where(eq(survey.id, input.id))
				.limit(1);
			return result[0];
		}),

	// Change survey status
	changeStatus: adminProcedure
		.input(surveyChangeStatusSchema)
		.handler(async ({ input, context }) => {
			// Verify ownership
			const existing = await db
				.select()
				.from(survey)
				.where(
					and(
						eq(survey.id, input.id),
						eq(survey.organizationId, context.activeOrganization.id),
					),
				)
				.limit(1);

			if (!existing[0]) {
				throw new Error("Survey not found");
			}

			await db
				.update(survey)
				.set({ status: input.status })
				.where(eq(survey.id, input.id));

			const result = await db
				.select()
				.from(survey)
				.where(eq(survey.id, input.id))
				.limit(1);
			return result[0];
		}),

	// Delete survey (owner only)
	delete: ownerProcedure
		.input(z.object({ id: z.string() }))
		.handler(async ({ input, context }) => {
			// Verify ownership
			const existing = await db
				.select()
				.from(survey)
				.where(
					and(
						eq(survey.id, input.id),
						eq(survey.organizationId, context.activeOrganization.id),
					),
				)
				.limit(1);

			if (!existing[0]) {
				throw new Error("Survey not found");
			}

			await db.delete(survey).where(eq(survey.id, input.id));
			return { success: true };
		}),

	// Bulk delete surveys (owner only)
	bulkDelete: ownerProcedure
		.input(z.object({ ids: z.array(z.string()) }))
		.handler(async ({ input, context }) => {
			// Verify all surveys belong to organization
			const surveysToDelete = await db
				.select()
				.from(survey)
				.where(
					and(
						inArray(survey.id, input.ids),
						eq(survey.organizationId, context.activeOrganization.id),
					),
				);

			if (surveysToDelete.length !== input.ids.length) {
				throw new Error("Some surveys not found or not accessible");
			}

			await db.delete(survey).where(inArray(survey.id, input.ids));
			return { success: true, deletedCount: surveysToDelete.length };
		}),
};

