export function QuestionRenderer({ question }: QuestionRendererProps) {
	const { answers, setAnswer, currentError } = useSurveyRunner();
	const value = answers.get(question.id);
	const error = currentError;

	const handleChange = (newValue: unknown) => {
		setAnswer(question.id, newValue);
	};

	switch (question.type) {
		case "text":
			return (
				<TextQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "textarea":
			return (
				<TextareaQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "multiple_choice":
			return (
				<ChoiceQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "checkbox":
			return (
				<CheckboxQuestion
					question={question}
					value={value as string[] | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "dropdown":
			return (
				<DropdownQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "rating":
			return (
				<RatingQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "nps":
			return (
				<NpsQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "linear_scale":
			return (
				<LinearScaleQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "date":
			return (
				<DateQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "email":
			return (
				<EmailQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "phone":
			return (
				<PhoneQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "file_upload":
			return (
				<FileUploadQuestion
					question={question}
					value={value}
					onChange={handleChange}
					error={error}
				/>
			);
		default:
			return (
				<div className="text-neutral-500">
					Unknown question type: {question.type}
				</div>
			);
	}
}

